struct ConstraintModel {
    constraints: PlIndexMap<PlSmallStr, ColumnConstraints>,


    opaque: Vec<Node>,

    memberships: Vec<Node>,

    not_nulls: Vec<(PlSmallStr, Node)>,
    num_bound_conjuncts: usize,
    normalized: bool,
    propagated: bool,
    dropped_equality: bool,
    unsat: bool,
}


fn model_and_chain(predicate: Node, schema: &Schema, expr_arena: &Arena<AExpr>) -> ConstraintModel {

    let mut constraints: PlIndexMap<PlSmallStr, ColumnConstraints> = PlIndexMap::new();
    let mut opaque: Vec<Node> = Vec::new();
    #[cfg_attr(not(feature = "is_in"), allow(unused_mut))]
    let mut memberships: Vec<Node> = Vec::new();
    let mut not_nulls: Vec<(PlSmallStr, Node)> = Vec::new();
    let mut edges: Vec<(PlSmallStr, PlSmallStr, Node)> = Vec::new();
    let mut num_bound_conjuncts = 0usize;
    let mut normalized = false;
    let mut unsat = false;

    for conjunct in MintermIter::new(predicate, expr_arena) {

        if expr_arena.get(conjunct).is_or()
            || !compares_in_literal_order(conjunct, schema, expr_arena)
        {
            opaque.push(conjunct);
            continue;
        }
        match classify_into_constraints(
            expr_arena.get(conjunct),
            schema,
            expr_arena,
            &mut constraints,
        ) {
            Classification::Unsat => {
                unsat = true;
                break;
            },
            Classification::Bound => num_bound_conjuncts += 1,
            Classification::Normalized => {
                num_bound_conjuncts += 1;
                normalized = true;
            },
            Classification::Equality(a, b) => edges.push((a, b, conjunct)),
            Classification::NotNull(name) => {
                not_nulls.push((name, conjunct));
                opaque.push(conjunct);
            },
            #[cfg(feature = "is_in")]
            Classification::Membership => memberships.push(conjunct),
            Classification::Opaque => opaque.push(conjunct),
        }
    }

    let mut unpropagated = None;
    let mut dropped_equality = false;

    if !unsat && !edges.is_empty() {
        let before = constraints.clone();
        if propagate_equalities(&mut constraints, &edges) {
            unpropagated = Some(before);
        }

        let fixed_value = |name| {
            constraints
                .get(name)
                .and_then(ColumnConstraints::fixed_value)
        };
        for (a, b, node) in &edges {
            if let (Some(x), Some(y)) = (fixed_value(a), fixed_value(b))
                && column_value(x, y.dtype()).as_ref() == Some(y)
            {
                dropped_equality = true;
            } else {
                opaque.push(*node);
            }
        }
    }

    if !unsat {
        unsat = constraints.values_mut().any(|cc| {
            cc.resolve_deferred();
            cc.unsat
        });
    }

    let propagated = !unsat
        && unpropagated.is_some_and(|mut before| {
            before
                .values_mut()
                .for_each(ColumnConstraints::resolve_deferred);
            emitted_comparisons(&before) != emitted_comparisons(&constraints)
        });

    ConstraintModel {
        constraints,
        opaque,
        memberships,
        not_nulls,
        num_bound_conjuncts,
        normalized,
        propagated,
        dropped_equality,
        unsat,
    }
}

pub(crate) struct ColumnBounds {
    pub name: PlSmallStr,

    pub lower: Option<(Scalar, bool)>,
    pub upper: Option<(Scalar, bool)>,

    pub excluded: Vec<Scalar>,

    pub allowed: Option<Vec<Scalar>>,
}

pub(crate) struct AndChainBounds {

    pub unsat: bool,
    pub columns: Vec<ColumnBounds>,
    pub other: Vec<Node>,
}

pub(crate) fn and_chain_bounds(
    predicate: Node,
    schema: &Schema,
    expr_arena: &Arena<AExpr>,
) -> AndChainBounds {
    let model = model_and_chain(predicate, schema, expr_arena);
    let columns = model
        .constraints
        .into_iter()
        .filter(|(_, cc)| {
            cc.lower.is_some()
                || cc.upper.is_some()
                || !cc.excluded.is_empty()
                || cc.allowed.is_some()
        })
        .map(|(name, cc)| ColumnBounds {
            name,
            lower: cc.lower,
            upper: cc.upper,
            excluded: cc.excluded.into_iter().collect(),
            allowed: cc.allowed.map(|allowed| allowed.into_iter().collect()),
        })
        .collect();
    AndChainBounds {
        unsat: model.unsat,
        columns,
        other: model.opaque,
    }
}

pub(crate) fn merge_filter_constraints(
    predicate: Node,
    schema: &Schema,
    maintain_errors: bool,
    expr_arena: &mut Arena<AExpr>,
) -> Option<Node> {
    let ConstraintModel {
        constraints,
        mut opaque,
        memberships,
        not_nulls,
        num_bound_conjuncts,
        normalized,
        propagated,
        dropped_equality,
        unsat,
    } = model_and_chain(predicate, schema, expr_arena);

    if unsat {

        let mut group = ExprPushdownGroup::Pushable;
        group.update_with_expr_rec(expr_arena.get(predicate), expr_arena, None);
        if group.blocks_pushdown(maintain_errors) {
            return None;
        }
        return Some(expr_arena.add(AExpr::Literal(Scalar::from(false).into())));
    }

    let comparisons = emitted_comparisons(&constraints);


    let tightened = comparisons.len() < num_bound_conjuncts;
    let redundant_not_nulls: Vec<Node> = not_nulls
        .into_iter()
        .filter(|(name, _)| constraints.get(name).is_some_and(|cc| cc.drops_nulls()))
        .map(|(_, node)| node)
        .collect();

    if !(tightened
        || normalized
        || propagated
        || dropped_equality
        || !redundant_not_nulls.is_empty())
    {
        return None;
    }
    opaque.retain(|node| !redundant_not_nulls.contains(node));


    opaque.extend(memberships);
    for (name, op, value) in comparisons {
        opaque.push(comparison_node(name, op, value.clone(), expr_arena));
    }
    Some(fold_and(opaque, expr_arena))
}

fn propagate_equalities(
    constraints: &mut PlIndexMap<PlSmallStr, ColumnConstraints>,
    edges: &[(PlSmallStr, PlSmallStr, Node)],
) -> bool {
    let mut emitted_changed = false;
    loop {
        let mut progressed = false;
        for (a, b, _) in edges {
            if a == b {
                continue;
            }

            let [Some(ca), Some(cb)] = constraints.get_disjoint_mut([a, b]) else {
                continue;
            };
            let (emitted_into_b, any_into_b) = cb.merge_from(ca);
            let (emitted_into_a, any_into_a) = ca.merge_from(cb);
            emitted_changed |= emitted_into_b || emitted_into_a;
            progressed |= any_into_b || any_into_a;
        }
        if !progressed {
            return emitted_changed;
        }
    }
}

fn classify_into_constraints(
    ae: &AExpr,
    schema: &Schema,
    expr_arena: &Arena<AExpr>,
    constraints: &mut PlIndexMap<PlSmallStr, ColumnConstraints>,
) -> Classification {
    match ae {
        AExpr::BinaryExpr { left, op, right } => {
            classify_comparison(*left, *op, *right, schema, expr_arena, constraints)
        },
        AExpr::Function {
            input,
            function,
            options: _,
        } => {

            let IRFunctionExpr::Boolean(func) = function else {
                return Classification::Opaque;
            };
            match func {


                IRBooleanFunction::Not => {
                    classify_negation(input[0].node(), schema, expr_arena, constraints)
                },
                #[cfg(feature = "is_between")]
                IRBooleanFunction::IsBetween { closed } => {
                    assert_eq!(
                        input.len(),
                        3,
                        "is_between has 3 inputs: value, lower, upper"
                    );
                    classify_is_between(
                        input[0].node(),
                        input[1].node(),
                        input[2].node(),
                        *closed,
                        schema,
                        expr_arena,
                        constraints,
                    )
                },

                #[cfg(feature = "is_in")]
                IRBooleanFunction::IsIn { .. } => {
                    let Some(col_name) = as_column(expr_arena.get(input[0].node())) else {
                        return Classification::Opaque;
                    };
                    let cc = column_constraints(constraints, schema, col_name);
                    match as_value_set(expr_arena.get(input[1].node()), &cc.dtype) {
                        Some(values) => {
                            cc.add_allowed(values.into_iter().collect());
                            Classification::Membership
                        },
                        None => Classification::Opaque,
                    }
                },

                IRBooleanFunction::IsNull => classify_null(
                    input[0].node(),
                    Nullability::Null,
                    schema,
                    expr_arena,
                    constraints,
                ),
                IRBooleanFunction::IsNotNull => classify_null(
                    input[0].node(),
                    Nullability::NonNull,
                    schema,
                    expr_arena,
                    constraints,
                ),
                _ => Classification::Opaque,
            }
        },


        AExpr::Element
        | AExpr::Explode { .. }
        | AExpr::Column(_)
        | AExpr::Literal(_)
        | AExpr::Cast { .. }
        | AExpr::Sort { .. }
        | AExpr::Gather { .. }
        | AExpr::SortBy { .. }
        | AExpr::Filter { .. }
        | AExpr::Agg(_)
        | AExpr::Ternary { .. }
        | AExpr::AnonymousAgg { .. }
        | AExpr::AnonymousFunction { .. }
        | AExpr::Eval { .. }
        | AExpr::Over { .. }
        | AExpr::Slice { .. }
        | AExpr::Len => Classification::Opaque,
        #[cfg(feature = "dtype-struct")]
        AExpr::StructField(_) => Classification::Opaque,
        #[cfg(feature = "dtype-struct")]
        AExpr::StructEval { .. } => Classification::Opaque,
        #[cfg(feature = "dynamic_group_by")]
        AExpr::Rolling { .. } => Classification::Opaque,
    }
}


